INSERT OR IGNORE INTO site_sections (id,draft,published,display_order) VALUES ('story','{"heading": "Not every day needs fixing.\nSometimes, you just need a coffee break.", "description": "Di sela tugas, meeting, dan jalanan yang padat, jeda kecil itu perlu. Kohee Break ada untuk momen itu: satu botol 250ml yang bisa kamu buka di mana pun kamu berhenti sebentar.\n\nJadi kalau hari ini terasa berat, berhenti dulu. Ambil sebotol. Lanjut lagi nanti.", "imageId": "", "visible": true}','{"heading": "Not every day needs fixing.\nSometimes, you just need a coffee break.", "description": "Di sela tugas, meeting, dan jalanan yang padat, jeda kecil itu perlu. Kohee Break ada untuk momen itu: satu botol 250ml yang bisa kamu buka di mana pun kamu berhenti sebentar.\n\nJadi kalau hari ini terasa berat, berhenti dulu. Ambil sebotol. Lanjut lagi nanti.", "imageId": "", "visible": true}',3);
